template:
PREFIX code: <http://aegis.gastown.local/ontology/>
SELECT ?consumer ?producer ?service ?method ?path
       ?consumerRepository ?consumerRevision ?consumerHash ?consumerExtractor
       ?producerRepository ?producerRevision ?producerHash ?producerExtractor
       ?consumerManifest ?consumerManifestHash ?producerManifest ?producerManifestHash
FROM <{input_graph}>
WHERE {
  ?consumer a code:HttpContractCandidate ; code:candidateRole "consumer" ;
    code:httpMethod ?method ; code:httpPath ?path ;
    code:repo ?consumerRepository ; code:revision ?consumerRevision ;
    code:sourceHash ?consumerHash ; code:extractorVersion ?consumerExtractor ;
    code:candidateTier "treesitter" ; code:candidateConfidence "candidate" ;
    code:sourceManifest ?consumerManifest .
  ?consumerManifest a code:Document ; code:httpCandidateContract "yupana-http-candidates/v1" ;
    code:httpCandidateProfile "python-fastapi-requests/v1" ;
    code:manifestBody ?consumerManifestBody ; code:manifestHash ?consumerManifestHash .
  OPTIONAL { ?consumer code:service ?service . }
  OPTIONAL {
    ?producer a code:HttpContractCandidate ; code:candidateRole "producer" ;
      code:service ?producerService ; code:httpMethod ?method ; code:httpPath ?path ;
      code:repo ?producerRepository ; code:revision ?producerRevision ;
      code:sourceHash ?producerHash ; code:extractorVersion ?producerExtractor ;
      code:resolution "exact" ; code:generatedClient false ;
      code:candidateTier "treesitter" ; code:candidateConfidence "candidate" ;
      code:sourceManifest ?producerManifest .
    ?producerManifest a code:Document ; code:httpCandidateContract "yupana-http-candidates/v1" ;
      code:httpCandidateProfile "python-fastapi-requests/v1" ;
      code:manifestBody ?producerManifestBody ; code:manifestHash ?producerManifestHash .
    ?consumer code:resolution "exact" ; code:generatedClient false .
    FILTER(?producerService = ?service)
    FILTER(?service = <{service}>)
    FILTER(?consumerRepository = '{consumer_repository}')
    FILTER(?producerRepository = '{producer_repository}')
    FILTER(?consumerRevision = '{consumer_revision}')
    FILTER(?producerRevision = '{producer_revision}')
    FILTER(?consumerHash = '{consumer_source_hash}')
    FILTER(?producerHash = '{producer_source_hash}')
    FILTER(?method != "UNKNOWN")
    FILTER(!REGEX(?path, "[*{}?#]"))
    FILTER NOT EXISTS {
      ?other a code:HttpContractCandidate ; code:candidateRole "producer" ;
        code:service ?service ; code:httpMethod ?method ; code:httpPath ?path .
      FILTER(?other != ?producer)
    }
  }
}
ORDER BY ?consumer ?producer
